from replay import simulate
from http import parse
PROG = ['python3', '-B', 'main.py']
MOD = 1 << 64


def fp(data):
    h = 0
    for c in data:
        h = (h * 257 + c + 1) % MOD
    return {'n': len(data), 'h': '%016x' % h}


def action(at, stream, kind, data, end):
    out = at.to_bytes(8, 'big') + stream.to_bytes(4, 'big') + kind.encode('ascii')
    if kind in ('H', 'h'):
        out += len(data).to_bytes(8, 'big')
        for n, v in data:
            out += len(n).to_bytes(8, 'big') + n
            out += len(v).to_bytes(8, 'big') + v
    else:
        out += len(data).to_bytes(8, 'big') + data
    return out + bytes((1 if end else 0,))


def field_fp(fields):
    out = bytearray()
    out += len(fields).to_bytes(8, 'big')
    for n, v in fields:
        out += len(n).to_bytes(8, 'big') + n
        out += len(v).to_bytes(8, 'big') + v
    return fp(bytes(out))


def expected(doc):
    cases = []
    for case in doc['cases']:
        rows = []
        for frame in case['frames']:
            kind = frame['Type']
            if kind == 'headers':
                if 'headers_kv' in frame:
                    pairs = [[k.encode(), v.encode()] for k, v in frame['headers_kv'].items()]
                else:
                    pairs = [[p[0].encode(), p[1].encode()] for p in frame['data_to_transfered']]
                rows.append({'Type': 'headers', 'data_to_transfered': pairs,
                             'End_Stream': frame.get('End_Stream', False)})
            elif kind == 'sleep':
                rows.append({'Type': 'sleep', 'Time_to_Stop': frame['Time_to_Stop']})
            else:
                rows.append({'Type': kind,
                             'data_to_transfered': frame['data_to_transfered'].encode(),
                             'End_Stream': frame.get('End_Stream', True)})
        cases.append({'name': case['name'], 'frames': rows})
    events = []
    for ev in doc['events']:
        row = {'kind': ev['kind'], 'at': ev['at']}
        if ev['kind'] == 'headers':
            row['stream'] = ev['stream']
            row['end'] = ev['end']
            row['fields'] = [[p[0].encode(), p[1].encode()] for p in ev['fields']]
        elif ev['kind'] == 'data':
            row['stream'] = ev['stream']
            row['end'] = ev['end']
            row['data'] = ev['data'].encode()
        events.append(row)
    replayed = simulate(cases, events, doc['timeout_ms'])
    records = []
    for row in replayed:
        sent = b''.join(action(t, row['stream'], k, d, e) for t, k, d, e in row['sent'])
        received = b''.join(action(t, row['stream'], k, d, e) for t, k, d, e in row['received'])
        body = b''.join(row['body'])
        records.append({'name': row['name'], 'stream': row['stream'], 'state': row['state'],
                        'at': row['at'], 'frames': row['frames'],
                        'request_frames': row['request_frames'],
                        'payload_bytes': row['payload_bytes'], 'sent': fp(sent),
                        'received': fp(received), 'response_frames': row['response_frames'],
                        'response_body': fp(body), 'origin_count': 0, 'flags': []})
    channels_out = []
    owner_seen = {}
    origin = {c['name']: 0 for c in doc['cases']}
    case_flags = {c['name']: set() for c in doc['cases']}
    request_frames = {c['name']: r['request_frames'] for c, r in zip(doc['cases'], records)}
    expect = {c['name']: c['expect'] for c in doc['cases']}
    for channel in doc['channels']:
        labels = [p['case'] for p in channel['parts']]
        chunks = [p['data'].encode() for p in channel['parts']]
        data = b''.join(chunks)
        bounds = [0]
        for chunk in chunks:
            bounds.append(bounds[-1] + len(chunk))
        reqs, error = parse(data)
        ends = [r['end'] for r in reqs]
        committed = [sum(1 for e in ends if e <= b) for b in bounds[1:]]
        out_reqs = []
        for r in reqs:
            segs = []
            for j in range(len(chunks)):
                low = max(r['start'], bounds[j])
                high = min(r['end'], bounds[j + 1])
                if high > low:
                    if segs and segs[-1][0] == labels[j]:
                        segs[-1][1] += high - low
                    else:
                        segs.append([labels[j], high - low])
            owner = None
            for j in range(len(chunks)):
                if bounds[j] <= r['start'] < bounds[j + 1]:
                    owner = labels[j]
                    break
            flags = set()
            if owner is None:
                flags.add('unattributed')
            if any(label != owner for label, _ in segs):
                flags.add('mixed_owner')
            if r['host_count'] == 0:
                flags.add('missing_host')
            elif r['host_count'] > 1:
                flags.add('multiple_host')
            if owner is not None:
                exp = expect[owner]
                if (r['method'] != exp['method'].encode()
                        or r['target'] != exp['target'].encode()
                        or r['host_count'] != 1
                        or r['host'].lower() != exp['host'].encode().lower()):
                    flags.add('identity')
                owner_seen[owner] = owner_seen.get(owner, 0) + 1
                if owner_seen[owner] > 1:
                    flags.add('extra')
                if request_frames[owner] == 0:
                    flags.add('unsent')
                origin[owner] += 1
                if 'identity' in flags:
                    case_flags[owner].add('identity')
                if 'mixed_owner' in flags:
                    case_flags[owner].add('mixed_origin')
            out_reqs.append({'start': r['start'], 'end': r['end'], 'method': fp(r['method']),
                             'target': fp(r['target']), 'host': fp(r['host']),
                             'host_count': r['host_count'], 'headers': field_fp(r['fields']),
                             'body': fp(r['body']), 'trailers': field_fp(r['trailers']),
                             'framing': r['framing'], 'owner': owner, 'owners': segs,
                             'flags': sorted(flags)})
        channels_out.append({'name': channel['name'], 'bytes': fp(data), 'requests': out_reqs,
                             'committed': committed, 'error': error})
    for case, record in zip(doc['cases'], records):
        name = case['name']
        count = origin[name]
        flags = set(case_flags[name])
        if record['request_frames'] > 0 and count == 0:
            flags.add('missing_origin')
        if count > 1:
            flags.add('extra_origin')
        if count > 0 and record['request_frames'] == 0:
            flags.add('unsent_origin')
        record['origin_count'] = count
        record['flags'] = sorted(flags)
    return {'cases': records, 'channels': channels_out}


NAMES = 'abcdefghijklmnopqrstuvwxyz'


def rand_name(rng, used):
    while True:
        name = ''.join(rng.choice(NAMES) for _ in range(rng.randrange(1, 6)))
        if name not in used:
            used.add(name)
            return name


