def gen_document(rng):
    used = set()
    doc = {'seed': ''.join(rng.choice(NAMES) for _ in range(rng.randrange(0, 5))),
           'definitions': [], 'timeout_ms': rng.randrange(1, 30),
           'cases': [], 'events': [], 'channels': []}
    cases = []
    for _ in range(rng.randrange(0, 4)):
        name = rand_name(rng, used)
        frames = []
        for _ in range(rng.randrange(0, 6)):
            kind = rng.choice(['headers', 'data', 'datagram', 'sleep'])
            if kind == 'headers':
                if rng.random() < 0.5:
                    frame = {'Type': 'headers',
                             'headers_kv': {rand_name(rng, set()):
                                            rng.choice(['a', 'b', 'v', 'xxx'])}}
                else:
                    frame = {'Type': 'headers',
                             'data_to_transfered': [
                                 [rng.choice([':method', 'a', 'host']),
                                  rng.choice(['GET', 'POST', '/x'])]
                                 for _ in range(rng.randrange(1, 4))]}
                if rng.random() < 0.4:
                    frame['End_Stream'] = rng.random() < 0.6
            elif kind == 'sleep':
                frame = {'Type': 'sleep', 'Time_to_Stop': rng.randrange(0, 12)}
            else:
                frame = {'Type': kind,
                         'data_to_transfered': rng.choice(['', 'abc', 'xyzxyzxyz'])}
                if rng.random() < 0.4:
                    frame['End_Stream'] = rng.random() < 0.6
            frames.append(frame)
        cases.append({'name': name, 'frames': frames,
                      'expect': {'method': rng.choice(['GET', 'POST']),
                                 'target': rng.choice(['/a', '/bb']),
                                 'host': rng.choice(['h.example', 'other'])}})
    doc['cases'] = cases
    names = [c['name'] for c in cases]
    for _ in range(rng.randrange(0, 7)):
        kind = rng.choice(['headers', 'data', 'close'])
        if kind == 'close':
            doc['events'].append({'at': rng.randrange(0, 40), 'kind': 'close'})
        elif kind == 'headers':
            doc['events'].append({'at': rng.randrange(0, 40), 'kind': 'headers',
                                  'stream': rng.randrange(0, 16),
                                  'fields': [[rng.choice([':status', 'x']),
                                              rng.choice(['200', 'zz'])]
                                             for _ in range(rng.randrange(1, 3))],
                                  'end': rng.random() < 0.6})
        else:
            doc['events'].append({'at': rng.randrange(0, 40), 'kind': 'data',
                                  'stream': rng.randrange(0, 16),
                                  'data': rng.choice(['', 'p', 'qq']),
                                  'end': rng.random() < 0.6})
    for _ in range(rng.randrange(0, 3)):
        parts = []
        for _ in range(rng.randrange(1, 5)):
            owner = rng.choice(names + [None]) if names else None
            parts.append({'case': owner, 'data': gen_http(rng)})
        doc['channels'].append({'name': rand_name(rng, used), 'parts': parts})
    return doc


def canonical(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=True, separators=(',', ':'))


def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
    trials = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    bad = 0
    for trial in range(trials):
        doc = gen_document(rng)
        raw = json.dumps(doc).encode('utf8')
        proc = subprocess.run(PROG, input=raw, capture_output=True, cwd='/workspace/project')
        if proc.returncode != 0:
            print('EXIT', proc.returncode, proc.stderr.decode()[:400]); bad += 1; continue
        got = json.loads(proc.stdout.decode('utf8'))
        want = expected(doc)
        if canonical(got) != canonical(want):
            bad += 1
            print('MISMATCH trial', trial)
            print('INPUT', json.dumps(doc))
            print('GOT  ', canonical(got)[:1200])
            print('WANT ', canonical(want)[:1200])
            if bad >= 2:
                break
    print('trials', trials, 'bad', bad)
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
